// Normaliza los tres origenes al esquema comun, valida y clasifica.
// Un solo lugar con las reglas: los nodos Set de arriba solo renombran.

// --- Decision de diseno abierta -------------------------------------------
// El esquema dice que "nombre" es obligatorio. Con false, un registro sin
// nombre igual entra al padron porque la clave natural es el correo.
// Ponelo en true y el padron pasa de 12 a 11, y la cuarentena de 4 a 5.
const NOMBRE_OBLIGATORIO = false;
// --------------------------------------------------------------------------

const VERDADEROS = ['true', 'yes', 'si', 's', '1'];
const PARTICULAS = ['da', 'de', 'del', 'la', 'las', 'los', 'van', 'von', 'di', 'san', 'santa', 'mac', 'mc'];
const HOY = new Date().toISOString().slice(0, 10);

function limpiar(t) {
  return (t === null || t === undefined ? '' : String(t)).trim().replace(/\s+/g, ' ');
}

function capitalizar(t) {
  return limpiar(t)
    .split(' ')
    .filter(Boolean)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(' ');
}

function normalizarEmail(t) {
  return limpiar(t).toLowerCase();
}

function emailValido(e) {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e);
}

function normalizarTelefono(t) {
  let d = (t === null || t === undefined ? '' : String(t)).replace(/\D/g, '');
  if (!d) return null;
  if (d.startsWith('54')) d = d.slice(2);
  if (d.startsWith('0')) d = d.slice(1);
  if (d.startsWith('9')) d = d.slice(1);
  // 341 15 555 0121 -> el 15 sobra cuando ya sacamos el 0 inicial
  if (d.length === 12 && d.slice(3, 5) === '15') d = d.slice(0, 3) + d.slice(5);
  return '+54' + d;
}

function partirNombre(completo) {
  const partes = limpiar(completo).split(' ').filter(Boolean);
  if (partes.length === 0) return { nombre: '', apellido: '' };
  if (partes.length === 1) return { nombre: partes[0], apellido: '' };
  // Regla declarada: el apellido es la ultima palabra, salvo que la anterior
  // sea una particula. Asi "Jorge Da Silva" no se parte mal.
  const anteUltima = partes[partes.length - 2].toLowerCase();
  const corte = PARTICULAS.includes(anteUltima) ? partes.length - 2 : partes.length - 1;
  return {
    nombre: partes.slice(0, corte).join(' '),
    apellido: partes.slice(corte).join(' '),
  };
}

function normalizarConsentimiento(v) {
  // Tres estados, no dos: si, no, y "nunca me lo dijeron".
  if (v === null || v === undefined || v === '') return { valor: false, declarado: false };
  if (typeof v === 'boolean') return { valor: v, declarado: true };
  // Sin acentos, para que "Si", "SI", "si" y "si" con tilde sean el mismo valor.
  const t = String(v)
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  return { valor: VERDADEROS.includes(t), declarado: true };
}

function existeEnElCalendario(f) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(f);
  if (!m) return false;
  const anio = Number(m[1]);
  const mes = Number(m[2]);
  const dia = Number(m[3]);
  const d = new Date(Date.UTC(anio, mes - 1, dia));
  return (
    d.getUTCFullYear() === anio && d.getUTCMonth() === mes - 1 && d.getUTCDate() === dia
  );
}

function normalizarFecha(valor, formato) {
  const v = limpiar(valor);
  if (!v) return { fecha: HOY, ok: true }; // fecha vacia: la completa el flujo
  let candidata = null;
  if (formato === 'iso') {
    candidata = v.slice(0, 10);
  } else {
    const m = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/.exec(v);
    if (m) {
      candidata = m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
    }
  }
  if (!candidata || !existeEnElCalendario(candidata)) return { fecha: null, ok: false };
  return { fecha: candidata, ok: true };
}

const salida = [];

for (const item of $input.all()) {
  const bruto = item.json;

  const email = normalizarEmail(bruto._email);

  let nombre = capitalizar(bruto._nombre || '');
  let apellido = capitalizar(bruto._apellido || '');
  if (!nombre && !apellido) {
    const partido = partirNombre(bruto._nombre_completo || '');
    nombre = capitalizar(partido.nombre);
    apellido = capitalizar(partido.apellido);
  }

  const consentimiento = normalizarConsentimiento(bruto._consentimiento);
  const fecha = normalizarFecha(bruto._fecha, bruto._formato_fecha);

  const registro = {
    email,
    nombre: nombre || null,
    apellido: apellido || null,
    telefono: normalizarTelefono(bruto._telefono),
    organizacion: limpiar(bruto._org) || null,
    cargo: limpiar(bruto._cargo) || null,
    consentimiento: consentimiento.valor,
    fecha_alta: fecha.fecha,
    origen: bruto._origen,
    _id_origen: bruto._id_origen,
  };

  // Validaciones, en orden. El primer motivo que aparece es el que se guarda.
  let motivo = null;
  if (!email) motivo = 'email_ausente';
  else if (!emailValido(email)) motivo = 'email_invalido';
  else if (!fecha.ok) motivo = 'fecha_invalida';
  else if (!consentimiento.declarado) motivo = 'consentimiento_ausente';
  else if (NOMBRE_OBLIGATORIO && !nombre) motivo = 'nombre_ausente';

  if (motivo) {
    salida.push({ json: { ...registro, _salida: 'cuarentena', _motivo: motivo, _original: bruto } });
  } else if (!consentimiento.valor) {
    salida.push({ json: { ...registro, _salida: 'sin_consentimiento', _motivo: 'consentimiento_negativo' } });
  } else {
    salida.push({ json: { ...registro, _salida: 'padron', _motivo: null } });
  }
}

return salida;

// Fusiona los duplicados por correo. No es "quedarse con uno": es combinar.

const PRIORIDAD = { web: 3, crm: 2, evento: 1 };
const CAMPOS = ['nombre', 'apellido', 'telefono', 'organizacion', 'cargo'];

const porEmail = new Map();

for (const item of $input.all()) {
  const actual = item.json;
  const previo = porEmail.get(actual.email);

  if (!previo) {
    porEmail.set(actual.email, { ...actual, _fuentes: [actual.origen] });
    continue;
  }

  // Gana la fuente de mayor prioridad como base del registro.
  const actualGana = PRIORIDAD[actual.origen] > PRIORIDAD[previo.origen];
  const base = { ...(actualGana ? actual : previo) };
  const otro = actualGana ? previo : actual;

  // Los huecos de la base se rellenan con lo que aporte la otra fuente.
  for (const campo of CAMPOS) {
    if (base[campo] === null || base[campo] === undefined || base[campo] === '') {
      base[campo] = otro[campo];
    }
  }

  // La fecha de alta es siempre la mas antigua de las dos.
  base.fecha_alta = [previo.fecha_alta, actual.fecha_alta].filter(Boolean).sort()[0];

  const fuentesPrevias = previo._fuentes || [previo.origen];
  base._fuentes = Array.from(new Set([...fuentesPrevias, actual.origen]));

  porEmail.set(actual.email, base);
}

return Array.from(porEmail.values()).map((json) => ({ json }));

// La verificacion del ejercicio: la cuenta tiene que cerrar.

const clasificados = $('Normalizar y validar').all().map((i) => i.json);
const padron = $('Fusionar duplicados').all().map((i) => i.json);

const contar = (salida) => clasificados.filter((r) => r._salida === salida).length;

const entradas = clasificados.length;
const enPadron = padron.length;
const cuarentena = contar('cuarentena');
const sinConsentimiento = contar('sin_consentimiento');
const duplicadosAbsorbidos = contar('padron') - enPadron;

const suma = enPadron + cuarentena + sinConsentimiento + duplicadosAbsorbidos;

const motivos = {};
for (const r of clasificados) {
  if (r._salida !== 'cuarentena') continue;
  motivos[r._motivo] = (motivos[r._motivo] || 0) + 1;
}

return [
  {
    json: {
      entradas,
      padron: enPadron,
      cuarentena,
      sin_consentimiento: sinConsentimiento,
      duplicados_absorbidos: duplicadosAbsorbidos,
      suma_de_salidas: suma,
      cierra: suma === entradas,
      motivos_de_cuarentena: motivos,
    },
  },
];
